			t.Fatalf("listener %s serves %v", listener, got)
		}
	}
	if steps, err := p.certSteps(t.Context(), d, cloudflare); err != nil || len(steps) != 0 {
		t.Fatalf("rerun planned %d: %v", len(steps), err)
	}
}

