func TestDesiredRecordsAreValidatedAndGenerationsMonotonic(t *testing.T) {
	if _, err := NewDesired(Key{Region: "XXX", Kind: "widget", Name: "a"}, 1, PolicyEnforce, widgetSpec{}); err == nil {
