	api.calls = nil
	if _, err := controller(t, api, store).Reconcile(t.Context(), 1); err != nil {
		t.Fatal(err)
	}
	if len(api.calls) != 2 {
		t.Fatalf("normalize calls=%v", api.calls)
	}
}

