		SchemaVersion: 1, DatabaseID: "0000000000AJ79CD84K5P2YR0E", PartitionID: "0000000000Z3WK359G2W66CVT8",
		ActiveRegions: []oci.Region{oci.RegionGRU}, Generation: 1,
