func TestProcessStatGone(t *testing.T) {
	for _, test := range []struct {
		err  error
		gone bool
	}{{syscall.ENOENT, true}, {syscall.ESRCH, true}, {syscall.EACCES, false}, {syscall.EIO, false}, {nil, false}} {
