		if err != nil {
			err = &os.PathError{Op: "read", Path: "/proc/123/stat", Err: err}
		}
		if got := processStatGone(err); got != test.gone {
			t.Errorf("stat error %v: gone=%v, want %v", err, got, test.gone)
		}
	}
}

