	cancel()
	l := nativeLab(t)
	l.Ctx = ctx
	l.CreatedNFTTables = []string{"owned-table"}
	l.Command = func(ctx context.Context, _ []string, _ CommandOptions) (CommandResult, error) {
		if e := ctx.Err(); e != nil {
			return CommandResult{}, e
		}
		return CommandResult{}, nil
