}
renewedWire, err := os.ReadFile(filepath.Join(renewedDirectory, "GRU", "amd64", "container.json"))
if err != nil {
	t.Fatal(err)
}
var renewedBundle release.ContainerBundle
if err := json.Unmarshal(renewedWire, &renewedBundle); err != nil {
