			gruError, sfoError := errors.New("GRU storage unavailable"), errors.New("SFO storage unavailable")
			fixture.env.storage = func(cell string) (releasechannel.ObjectClient, error) {
				if cell == "GRU" {
					return nil, gruError
				}
				if failBoth && cell == "SFO" {
					return nil, sfoError
				}
				return storage(cell)
			}
