			name string
			wire []byte
		}{
			{name: "malformed", wire: []byte("{")},
			{name: "invalid timestamp", wire: []byte(`{"updated_at":"invalid"}`)},
			{name: "oversized", wire: bytes.Repeat([]byte(" "), maxStatusBytes+1)},
