	// window only completes on a reported sample.
	soak = newSoak()
	for _, s := range []SoakSample{sample(0, 77), sample(20*time.Second, 0), gap(40 * time.Second), gap(time.Minute)} {
		if done, err := soak.Observe(s); done || err != nil {
