		t.Fatalf("soak after a gap = %t %v", done, err)
	}

	// A gap does not hide the controller-owned fields.
	soak = newSoak()
	if _, err := soak.Observe(sample(0, 77)); err != nil {
		t.Fatal(err)
	}
