	stressWrite(t, filepath.Join(group, "cgroup.procs"), fmt.Sprintf("%d\n", pid))
	r, e := PressureCgroupInventory(group, []int{pid}, map[int]string{pid: "cpu_worker"}, "/proc")
	if e != nil {
		t.Fatal(e)
	}
