	}
	stressWrite(t, filepath.Join(group, "cgroup.procs"), fmt.Sprintf("%d\n", pid))
	stressLink(t, root, filepath.Join(group, "unexpected"))
	if _, e := AssertExclusiveCgroup(group, []int{pid}); e == nil || !strings.Contains(e.Error(), "symlinks") {
		t.Fatal(e)
	}
}

