	baked := filepath.Join(dir, "new-baked")
	supported := []byte("#!/bin/sh\n[ \"$*\" = 'netbird agent run --help' ]\n")
	if err := os.WriteFile(baked, supported, 0755); err != nil {
		t.Fatal(err)
