			return `{"version":1,"host":{"identity_key_file":"` + key + `","self_update_root":"` + filepath.Join(dir, "elsewhere") + `"}}`, proof
		}, false, false},
	} {
		t.Run(tc.name, func(t *testing.T) {
			dir := t.TempDir()
			root := filepath.Join(dir, "lib", "terrascale-orchestrator")
