					restarted = append(restarted, unit)
					return nil
				})
				return output.String(), err
			}
			if _, err := invoke("prepare", "--root", root, "--owner", owner, "--unit", tc.unit, "--baked-binary", baked); err != nil {
				t.Fatal(err)
