			if err != nil {
				t.Fatal(err)
			}
			keyFile := filepath.Join(dir, "identity.key")
			if err := os.WriteFile(keyFile, []byte(base64.StdEncoding.EncodeToString(private)+"\n"), 0o600); err != nil {
				t.Fatal(err)
			}
