				private = f.nodePrivate
				keyID, err := trust.KeyID(f.nodePublic)
				if err != nil {
					t.Fatal(err)
				}
				encoded, err := trust.EncodeDelegatedPublicKey(f.nodePublic)
				if err != nil {
					t.Fatal(err)
				}
