		if !clockHealthy.Load() {
			return authority.ErrClockUnhealthy
		}
		return nil
	}})
	if err != nil {
		t.Fatal(err)
	}
	t.Cleanup(func() { _ = auth.Close() })
	directory := t.TempDir()
	if err := os.Chmod(directory, 0o700); err != nil {
