		EnvPeerPort:          "9443",
		EnvDataDirectory:     "/srv/ts-managed/terrabase/data",
		EnvBundleExtract:     "/srv/ts-managed/terrabase/bundle",
		EnvPeerCertificate:   "/srv/ts-managed/terrabase/tls/member.pem",
