	other := testChainID
	other.Cell = "sfo"
	foreign := rotate(t, other, start, []ed25519.PrivateKey{r1}, r0, r1)
	if _, err := VerifyRootChain(genesis, testChainID, RootChain{Version: 1, Rotations: []SignedRotation{foreign}}); !errors.Is(err, ErrScopeMismatch) {
