	if err := RotationCurrent(good, testChainAt); err != nil {
		t.Errorf("current rotation: %v", err)
	}
	if err := RotationCurrent(good, testChainAt.Add(time.Hour)); !errors.Is(err, ErrExpired) {
		t.Errorf("expired rotation: %v", err)
	}
}

