	rendered, names, err := Render(t.Context(), vault, testTarget.VaultID, "gru-1", template)
	if err != nil {
		t.Fatal(err)
	}
	if want := "authSecret: \"a\\\"b\\\\\"\nkey: \"c2VjcmV0\"\nagain: \"a\\\"b\\\\\"\n"; string(rendered) != want {
		t.Fatalf("rendered %q", rendered)
