		Name: authority.ControlStreamName, Subjects: []string{"ts.control.*.>"},
		Storage: jetstream.FileStorage, Replicas: r3BrokerCount, MaxBytes: -1,
	})
	if err != nil {
		t.Fatalf("create control log required by production host controller: %v", err)
	}
