	root := t.TempDir()
	material := filepath.Join(root, "material")
	guest := filepath.Join(material, "controllers", "seed-a", "guest-root", "var", "lib", "terrascale-orchestrator-secrets")
	if err := os.MkdirAll(guest, 0o700); err != nil {
